package com.company.platform.analytics.application;
import com.fasterxml.jackson.databind.JsonNode;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class AnalyticsEventConsumer {private final JdbcTemplate jdbc;public AnalyticsEventConsumer(JdbcTemplate j){jdbc=j;}
 @Transactional @KafkaListener(topics={"marketplace.events","commerce.events","order.events","payment.events","inventory.events","fulfillment.events"},groupId="analytics-service",containerFactory="analyticsKafkaListenerContainerFactory") public void onEvent(JsonNode event){UUID eventId=parse(event.path("eventId").asText(null)),tenant=parse(event.path("tenantId").asText(null));String correlation=event.path("correlationId").asText(null);if(eventId==null||tenant==null||correlation==null||correlation.isBlank())throw new IllegalArgumentException("analytics event requires eventId, tenantId and correlationId");if(jdbc.queryForObject("SELECT COUNT(*) FROM analytics_events WHERE event_id=?",Long.class,eventId)>0)return;String type=event.path("payload").path("eventType").asText(event.path("eventType").asText("UNKNOWN"));JsonNode body=event.path("payload").path("data");if(body.isMissingNode()||body.isNull())body=event.path("payload");UUID aggregate=parse(event.path("aggregateId").asText(event.path("payload").path("aggregateId").asText(null)));Instant at=parseInstant(event.path("timestamp").asText(event.path("occurredAt").asText(null)));if(at==null)at=Instant.now();jdbc.update("INSERT INTO analytics_events(event_id,tenant_id,event_type,aggregate_id,correlation_id,occurred_at,payload) VALUES(?,?,?,?,?,?,?::jsonb)",eventId,tenant,type,aggregate,correlation,at,body.toString());BigDecimal amount=number(body,"total",number(body,"amount",null));BigDecimal quantity=number(body,"quantity",null);UUID order=parse(body.path("orderId").asText(null));UUID product=parse(body.path("productId").asText(body.path("sellableProductId").asText(null)));jdbc.update("INSERT INTO analytics_metrics(event_id,tenant_id,event_type,aggregate_id,order_id,product_id,quantity,amount,currency,occurred_at) VALUES(?,?,?,?,?,?,?,?,?,?)",eventId,tenant,type,aggregate,order,product,quantity,amount,body.path("currency").asText(null),at);}
 private BigDecimal number(JsonNode n,String key,BigDecimal fallback){return n.path(key).isNumber()?n.path(key).decimalValue():fallback;}private UUID parse(String s){if(s==null||s.isBlank())return null;try{return UUID.fromString(s);}catch(IllegalArgumentException e){throw new IllegalArgumentException("invalid analytics UUID",e);}}private Instant parseInstant(String s){try{return s==null?null:Instant.parse(s);}catch(Exception e){return null;}}
}
